export const PI = 3.14159;

export function area(radius) {
  return PI * radius * radius;
}

export default class Circle {
  constructor(radius) {
    this.radius = radius;
  }
}

import Circle, { area, PI as pi } from "./math.js";
import * as math from "./math.js";

console.log(pi);
console.log(area(2));
console.log(math.area(1));
console.log(new Circle(3).radius);

class Product {
  #stock;                       // private field

  constructor(name, price, stock = 0) {
    this.name = name;
    this.price = price;
    this.#stock = stock;
  }

  get inStock() {
    return this.#stock > 0;
  }

  sell(quantity = 1) {
    if (quantity > this.#stock) {
      throw new Error(`Only ${this.#stock} left`);
    }
    this.#stock -= quantity;
    return this.#stock;
  }

  static fromJSON(json) {
    const data = JSON.parse(json);
    return new Product(data.name, data.price, data.stock);
  }
}

const pen = new Product("Pen", 2, 3);
console.log(pen.inStock);
console.log(pen.sell(2));
console.log(pen.sell());
console.log(pen.inStock);
console.log(typeof Product);

const book = Product.fromJSON('{"name":"Book","price":12,"stock":1}');
console.log(book.name);

class Animal {
  constructor(name) {
    this.name = name;
  }
  speak() {
    return `${this.name} makes a sound`;
  }
  toString() {
    return `Animal(${this.name})`;
  }
}

class Dog extends Animal {
  speak() {
    return `${this.name} barks`;             // override
  }
}

class Puppy extends Dog {
  constructor(name, ageWeeks) {
    super(name);                             // parent constructor first
    this.ageWeeks = ageWeeks;
  }
  speak() {
    return `${super.speak()} softly`;        // extend the parent's version
  }
}

const rex = new Puppy("Rex", 8);
console.log(rex.speak());
console.log(rex.ageWeeks);
console.log(rex instanceof Dog);
console.log(rex instanceof Animal);
console.log(String(rex));

class Counter {
  count = 0;                     // public field with an initial value
  increment() {
    this.count++;
    return this.count;
  }
}

const counter = new Counter();
const detached = counter.increment;   // method taken off the object
try {
  detached();
} catch (error) {
  console.log(error.name);            // this is undefined inside the call
}

const bound = counter.increment.bind(counter);
console.log(bound());
console.log([1, 2, 3].map(() => counter.increment()).join(", "));
